/*
 * Linux platform backend: Wayland window + EGL/OpenGL context + xkb input.
 *
 * Implements the window/input half of platform.h. Window management uses the
 * xdg-shell stable protocol (its client glue is generated by wayland-scanner in
 * build.sh). The GL context is created via EGL on a wl_egl_window. Keyboard
 * handling decodes keysyms and UTF-8 text through libxkbcommon and implements
 * key repeat client-side (Wayland leaves that to clients); pointer handling
 * tracks motion, buttons and the scroll wheel.
 *
 * PLATFORM_WINDOW_HEADLESS skips the Wayland surface entirely and creates a
 * pbuffer-backed context; the renderer then draws into an offscreen target.
 */

#include "platform.h"

#include <wayland-client.h>
#include <wayland-cursor.h>
