#include <unistd.h>

#ifndef XKB_KEY_XF86AudioPlay
#define XKB_KEY_XF86AudioPlay 0x1008FF14
#endif
#ifndef XKB_KEY_XF86AudioPause
#define XKB_KEY_XF86AudioPause 0x1008FF31
#endif
#ifndef XKB_KEY_XF86AudioNext
#define XKB_KEY_XF86AudioNext 0x1008FF17
#endif
#ifndef XKB_KEY_XF86AudioPrev
#define XKB_KEY_XF86AudioPrev 0x1008FF16
#endif

struct Platform_Window {
    /* wayland core */
    struct wl_display    *display;
    struct wl_registry   *registry;
    struct wl_compositor *compositor;
    struct wl_seat       *seat;
    struct wl_shm        *shm;
    struct xdg_wm_base   *wm_base;
    struct wl_surface    *surface;
    struct xdg_surface   *xdg_surface;
    struct xdg_toplevel  *xdg_toplevel;

    struct zxdg_decoration_manager_v1   *decor_manager;
    struct zxdg_toplevel_decoration_v1  *toplevel_decor;

    /* input devices */
    struct wl_keyboard   *keyboard;
    struct wl_pointer    *pointer;
    struct wl_surface    *cursor_surface;
    struct wl_cursor_theme *cursor_theme;
    struct wl_cursor      *cursors[PLATFORM_CURSOR_COUNT];
    Platform_Cursor        cursor_kind;
    uint32_t               pointer_enter_serial;
    uint32_t               last_input_serial;
    b32                    pointer_focused;
    b32                    keyboard_focused;
    struct xkb_context   *xkb_ctx;
    struct xkb_keymap    *xkb_keymap;
    struct xkb_state     *xkb_state;

    /* egl */
    struct wl_egl_window *egl_window;
    EGLDisplay            egl_display;
    EGLContext            egl_context;
    EGLSurface            egl_surface;
    EGLConfig             egl_config;

    u32 width, height;
    u32 pending_w, pending_h;
    u32 flags;
    b32 headless;
    b32 should_close;
    b32 configured;
    b32 maximized;
    b32 any_event;

    /* live input accumulators (committed into the snapshot on poll) */
    b32 key_down[PLATFORM_KEY_COUNT];
    b32 key_pressed[PLATFORM_KEY_COUNT];
    b32 key_released[PLATFORM_KEY_COUNT];
    b32 ctrl, shift, alt;

    vec2 mouse_pos, last_mouse_pos;
    b32 mouse_down[PLATFORM_MOUSE_BUTTON_COUNT];
    b32 mouse_pressed[PLATFORM_MOUSE_BUTTON_COUNT];
    b32 mouse_released[PLATFORM_MOUSE_BUTTON_COUNT];
    f32 scroll_x, scroll_y;
    b32 scroll_precise;
    b32 axis_is_finger;

    u8  text[64];
    u32 text_len;

    /* key repeat */
    s32 repeat_rate;       /* per second, 0 = disabled */
    s32 repeat_delay_ms;
    Platform_Key repeat_key;
    xkb_keycode_t repeat_keycode;
    f64 repeat_next;
};

static void set_opaque_region(Platform_Window *w);

/* X cursor themes use a few aliases for the same common UI shape. */
static struct wl_cursor *load_theme_cursor(struct wl_cursor_theme *theme,
                                           Platform_Cursor cursor) {
    const char *names[3] = {0};
    switch (cursor) {
        case PLATFORM_CURSOR_DEFAULT:
            names[0] = "default"; names[1] = "left_ptr"; break;
        case PLATFORM_CURSOR_TEXT:
            names[0] = "text"; names[1] = "xterm"; break;
        case PLATFORM_CURSOR_HAND:
            names[0] = "pointer"; names[1] = "hand2"; names[2] = "hand"; break;
        case PLATFORM_CURSOR_MOVE:
            names[0] = "move"; names[1] = "fleur"; names[2] = "all-scroll"; break;
        case PLATFORM_CURSOR_GRAB:
            names[0] = "grab"; names[1] = "openhand"; break;
        case PLATFORM_CURSOR_GRABBING:
            names[0] = "grabbing"; names[1] = "closedhand"; break;
        case PLATFORM_CURSOR_RESIZE_HORIZONTAL:
            names[0] = "ew-resize"; names[1] = "col-resize"; break;
        case PLATFORM_CURSOR_RESIZE_VERTICAL:
            names[0] = "ns-resize"; names[1] = "row-resize"; break;
        case PLATFORM_CURSOR_RESIZE_NWSE:
            names[0] = "nwse-resize"; names[1] = "se-resize"; break;
        case PLATFORM_CURSOR_RESIZE_NESW:
            names[0] = "nesw-resize"; names[1] = "sw-resize"; break;
        case PLATFORM_CURSOR_CROSSHAIR:
            names[0] = "crosshair"; break;
        case PLATFORM_CURSOR_NOT_ALLOWED:
            names[0] = "not-allowed"; names[1] = "circle"; break;
        case PLATFORM_CURSOR_HIDDEN:
        case PLATFORM_CURSOR_COUNT:
            break;
    }
    for (u32 i = 0; i < CORE_ARRAY_COUNT(names) && names[i]; i++) {
        struct wl_cursor *result = wl_cursor_theme_get_cursor(theme, names[i]);
        if (result) return result;
    }
    return 0;
}

static void apply_cursor(Platform_Window *w) {
    if (!w->pointer || !w->pointer_focused) return;

    if (w->cursor_kind == PLATFORM_CURSOR_HIDDEN) {
        wl_pointer_set_cursor(w->pointer, w->pointer_enter_serial, 0, 0, 0);
        return;
    }

    struct wl_cursor *cursor = w->cursors[w->cursor_kind];
    if (!cursor) cursor = w->cursors[PLATFORM_CURSOR_DEFAULT];
    if (!cursor || !cursor->image_count || !w->cursor_surface) return;

    struct wl_cursor_image *image = cursor->images[0];
    struct wl_buffer *buffer = wl_cursor_image_get_buffer(image);
    if (!buffer) return;

    wl_pointer_set_cursor(w->pointer, w->pointer_enter_serial,
                          w->cursor_surface, image->hotspot_x, image->hotspot_y);
    wl_surface_attach(w->cursor_surface, buffer, 0, 0);
    wl_surface_damage(w->cursor_surface, 0, 0, image->width, image->height);
    wl_surface_commit(w->cursor_surface);
}

/* ---- keysym -> Platform_Key ---- */

static Platform_Key map_keysym(xkb_keysym_t sym) {
    switch (sym) {
        case XKB_KEY_Escape:       return PLATFORM_KEY_ESCAPE;
        case XKB_KEY_Return:
        case XKB_KEY_KP_Enter:     return PLATFORM_KEY_ENTER;
        case XKB_KEY_space:        return PLATFORM_KEY_SPACE;
        case XKB_KEY_Tab:
        case XKB_KEY_ISO_Left_Tab: return PLATFORM_KEY_TAB;
        case XKB_KEY_BackSpace:    return PLATFORM_KEY_BACKSPACE;
        case XKB_KEY_Delete:       return PLATFORM_KEY_DELETE;
        case XKB_KEY_Home:         return PLATFORM_KEY_HOME;
        case XKB_KEY_End:          return PLATFORM_KEY_END;
        case XKB_KEY_Page_Up:      return PLATFORM_KEY_PAGE_UP;
        case XKB_KEY_Page_Down:    return PLATFORM_KEY_PAGE_DOWN;
        case XKB_KEY_Left:         return PLATFORM_KEY_LEFT;
        case XKB_KEY_Right:        return PLATFORM_KEY_RIGHT;
        case XKB_KEY_Up:           return PLATFORM_KEY_UP;
        case XKB_KEY_Down:         return PLATFORM_KEY_DOWN;
        case XKB_KEY_F1:           return PLATFORM_KEY_F1;
        case XKB_KEY_comma:        return PLATFORM_KEY_COMMA;
        case XKB_KEY_F2:           return PLATFORM_KEY_F2;
        case XKB_KEY_XF86AudioPlay:
        case XKB_KEY_XF86AudioPause: return PLATFORM_KEY_MEDIA_PLAY_PAUSE;
        case XKB_KEY_XF86AudioNext: return PLATFORM_KEY_MEDIA_NEXT;
        case XKB_KEY_XF86AudioPrev: return PLATFORM_KEY_MEDIA_PREV;
        default: break;
    }
    if (sym >= XKB_KEY_a && sym <= XKB_KEY_z)
        return (Platform_Key)(PLATFORM_KEY_A + (sym - XKB_KEY_a));
    if (sym >= XKB_KEY_A && sym <= XKB_KEY_Z)
        return (Platform_Key)(PLATFORM_KEY_A + (sym - XKB_KEY_A));
    return PLATFORM_KEY_UNKNOWN;
}

